// any method can block, even deep inside an old library
void checkout(Basket b) throws InterruptedException {
    Payment paid = bank.charge(b);         // a blocking network read: unmounts here
    Thread.sleep(Duration.ofMillis(30));   // unmounts here too
    orders.save(b, paid);                  // a plain database call over a socket: unmounts
}

// run it on a virtual thread; nothing in checkout() knows
Thread.ofVirtual().name("checkout-", 0).start(() -> {
    try { checkout(basket); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
});

